import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// 1. FONT LOADER
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// 2. SCHEMA


export type CryptoClockProps = Record<string, any>;

// Helper: Checkmark Icon
const CheckIcon = ({ progress, color }: { progress: number; color: string }) => {
    return (
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <path 
                d="M20 6L9 17l-5-5" 
                strokeDasharray="30"
                strokeDashoffset={interpolate(progress, [0, 1], [30, 0])} 
            />
        </svg>
    )
};

// Helper: Scales Icon
const ScalesIcon = ({ color, opacity, progress }: { color: string, opacity: number, progress: number }) => {
    const scale = interpolate(progress, [0, 1], [0.8, 1]);
    const pathLen = interpolate(progress, [0, 1], [100, 0]);
    
    return (
        <svg width="120" height="120" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ opacity, transform: `scale(${scale})` }}>
            <path d="M12 3v18" strokeDasharray="100" strokeDashoffset={pathLen} />
            <path d="M6 6h12" strokeDasharray="100" strokeDashoffset={pathLen} />
            <path d="M6 6l-3 5a3 3 0 0 0 6 0L6 6z" strokeDasharray="100" strokeDashoffset={pathLen} />
            <path d="M18 6l-3 5a3 3 0 0 0 6 0L18 6z" strokeDasharray="100" strokeDashoffset={pathLen} />
            <path d="M12 21h-4" strokeDasharray="100" strokeDashoffset={pathLen} />
            <path d="M12 21h4" strokeDasharray="100" strokeDashoffset={pathLen} />
        </svg>
    );
};

// 3. COMPONENT
const CryptoClock: React.FC<CryptoClockProps> = ({
  backgroundColor = "#050510",
  transparentBackground = false,
  durationInSeconds = 10,
  bullColor = "#00ffa3",
  glowColor = "#00d2ff",
  centerText = "WAGS keeps you compliant",
  textColor = "#ffffff",
}) => {
  // Load Fonts
  useFontLoader(["Orbitron", "Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation Constants
  const items = [
      "Daily loss limit",
      "Position sizing",
      "No overnight holds",
      "Drawdown monitoring",
      "Time restrictions"
  ];
  
  const STAGGER = 20; // Frames between each item appearing
  const START_DELAY = 15;
  const LIST_EXIT_START = START_DELAY + (items.length * STAGGER) + 40;

  // --- RENDER HELPERS ---
  const renderList = () => {
      // Calculate list exit transition (slide up and fade)
      const exitProgress = spring({
          frame: frame - LIST_EXIT_START,
          fps,
          config: { damping: 20 }
      });
      
      const listContainerY = interpolate(exitProgress, [0, 1], [0, -100]);
      const listContainerOpacity = interpolate(exitProgress, [0, 1], [1, 0]);

      return (
          <div style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: `translate(-50%, calc(-50% + ${listContainerY}px))`,
              opacity: listContainerOpacity,
              display: 'flex',
              flexDirection: 'column',
              gap: 25,
              width: '100%',
              maxWidth: 550,
              padding: '0 20px'
          }}>
              {items.map((text, index) => {
                  const startFrame = START_DELAY + index * STAGGER;
                  
                  // Item Entrance
                  const progress = spring({
                      frame: frame - startFrame,
                      fps,
                      config: { damping: 14, stiffness: 100 }
                  });
                  
                  // Checkmark Trigger
                  const checkProgress = spring({
                      frame: frame - startFrame - 10, // Check comes 10 frames after text
                      fps,
                      config: { damping: 12, stiffness: 80 }
                  });

                  // Item Styles
                  const y = interpolate(progress, [0, 1], [30, 0]);
                  const opacity = interpolate(progress, [0, 1], [0, 1]);
                  const isChecked = checkProgress > 0.5;

                  return (
                      <div key={index} style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 20,
                          transform: `translateY(${y}px)`,
                          opacity
                      }}>
                          {/* Checkbox / Icon Container */}
                          <div style={{
                              width: 40,
                              height: 40,
                              minWidth: 40,
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              border: `2px solid ${isChecked ? bullColor : textColor}44`,
                              borderRadius: 8,
                              backgroundColor: isChecked ? `${bullColor}22` : 'transparent',
                              boxShadow: isChecked ? `0 0 15px ${bullColor}44` : 'none',
                              transition: 'all 0.2s ease-out' 
                          }}>
                              <CheckIcon progress={checkProgress} color={bullColor} />
                          </div>

                          {/* Text */}
                          <div style={{
                              fontFamily: 'Inter, sans-serif',
                              fontSize: 32,
                              fontWeight: 600,
                              color: isChecked ? textColor : `${textColor}AA`,
                              textDecoration: isChecked ? 'none' : 'none',
                              transition: 'color 0.3s'
                          }}>
                              {text}
                          </div>
                      </div>
                  );
              })}
          </div>
      );
  };

  const renderFinalScreen = () => {
      const startFrame = LIST_EXIT_START + 10;
      
      const progress = spring({
          frame: frame - startFrame,
          fps,
          config: { damping: 15 }
      });

      if (frame < startFrame) return null;

      return (
          <AbsoluteFill style={{
              justifyContent: 'center',
              alignItems: 'center',
              zIndex: 10
          }}>
             {/* Glow Burst */}
             <div style={{
                 position: 'absolute',
                 width: 800,
                 height: 800,
                 background: `radial-gradient(circle, ${bullColor}22 0%, transparent 60%)`,
                 opacity: interpolate(progress, [0, 1], [0, 1]),
                 transform: `scale(${interpolate(progress, [0, 1], [0.5, 1])})`
             }} />

             <div style={{
                 display: 'flex',
                 flexDirection: 'column',
                 alignItems: 'center',
                 gap: 30,
                 transform: `translateY(${interpolate(progress, [0, 1], [50, 0])}px)`,
                 opacity: progress
             }}>
                 <ScalesIcon color={bullColor} opacity={1} progress={progress} />
                 
                 <h1 style={{
                     fontFamily: 'Orbitron, sans-serif',
                     fontSize: 48,
                     fontWeight: 900,
                     textAlign: 'center',
                     color: textColor,
                     margin: 0,
                     textTransform: 'uppercase',
                     maxWidth: 800,
                     lineHeight: 1.2,
                     textShadow: `0 0 30px ${bullColor}66`
                 }}>
                     {centerText}
                 </h1>
             </div>
          </AbsoluteFill>
      );
  };

  // --- MAIN RENDER ---
  return (
    <AbsoluteFill style={{ backgroundColor: "#000" }}>
      {!transparentBackground && <AbsoluteFill style={{ background: backgroundColor }} />}
      
      {/* Background Grid */}
      <AbsoluteFill style={{ opacity: 0.08 }}>
         <div style={{
             width: '100%', height: '100%',
             backgroundImage: `linear-gradient(${glowColor} 1px, transparent 1px), linear-gradient(90deg, ${glowColor} 1px, transparent 1px)`,
             backgroundSize: '50px 50px',
             backgroundPosition: 'center'
         }} />
      </AbsoluteFill>

      {renderList()}
      {renderFinalScreen()}

      {/* Vignette Overlay */}
      <AbsoluteFill style={{
          background: 'radial-gradient(circle at center, transparent 30%, #000000CC 100%)',
          pointerEvents: 'none',
          zIndex: 50
      }} />

    </AbsoluteFill>
  );
};

export default CryptoClock;